1	function [oup, dbg] = cordic(defines, x, y, z)
2	% [oup, dbg] = cordic(n_iter, mode_rotation, lut_width, lut_depth, gain_width, xy_width, z_width, x, y, z)
3	% This is a behavioral model for CORDIC algorithm.
4	% P.S. The angles are based on DEGREE's.
5	% In case degree instead of radioan replace atan, cos and sin with atand, cosd, and sind
6	% GENERATE ATAN & GAIN LUTs'
7	n_iter        = defines.gp_nr_iter;
8	mode_rotation = defines.gp_mode_rot_vec; 
9	lut_width     = defines.gp_angle_width;
10	lut_depth     = defines.gp_angle_depth;
11	gain_width    = defines.gp_gain_width; 
12	xy_width      = defines.gp_xy_width;
13	z_width       = defines.gp_z_width;
14	testcase      = defines.testcase;
15	
16	for i = 1 : lut_depth
17	    j           = i-1;
18	    tan_lut(i)  = 2^-j;
19	    atan_lut(i) = atan(2^-j);% RADIAN
20	    gain_lut(i) = 1/sqrt(1+2^(-2*j));
21	end
22	gain = 0.607252959138945;%prod(gain_lut);
23	
24	x_init = x;
25	y_init = y;
26	z_init = z;
27	
28	for i = 1 : n_iter,
29	    if i>1,
30	      % FUNCTIONAL MODE
31	        if mode_rotation,
32	            % ROTATION
33	            if (z(i-1) >= 0),
34	                d(i) = 1;
35	            else
36	                d(i) = -1;
37	            end
38	        else
39	            % VECTORING
40	            if (y(i-1) < 0),
41	                d(i) = 1;
42	            else
43	                d(i) = -1;
44	            end
45	        end
46	    else
47	        % INITIALIZATION MODE
48	        if mode_rotation,
49	            % ROTATION
50	            if (z_init >= 0),
51	                d(i) = 1;
52	            else
53	                d(i) = -1;
54	            end
55	        else
56	            % VECTORING
57	            if (y_init < 0),
58	                d(i) = 1;
59	            else
60	                d(i) = -1;
61	            end
62	        end
63	    end    
64	    % CORDIC ALGORITHM
65	    if i == 1,
66	        x(i) = x_init - y_init*d(i)*2^-(i-1);
67	        y(i) = y_init + x_init*d(i)*2^-(i-1);
68	        z(i) = z_init - d(i)*atan_lut(i);
69	    else
70	        x(i) = x(i-1) - y(i-1)*d(i)*2^-(i-1);
71	        y(i) = y(i-1) + x(i-1)*d(i)*2^-(i-1);
72	        z(i) = z(i-1) - d(i)*atan_lut(i);
73	    end
74	end
75	
76	% CORDIC OUTPUT
77	if mode_rotation
78	    % ROTATION MODE
79	    cos_z = x(end)*gain
80	    sin_z = y(end)*gain
81	
82	    cos_ref = cos(z_init)
83	    sin_ref = sin(z_init)
84	    
85	    %dat = [floor(cos_z*2^(xy_width+ceil(log2(n_iter)))) floor(sin_z*2^(xy_width+ceil(log2(n_iter))))];
86	    %ref = [floor(cos_ref*2^(xy_width+ceil(log2(n_iter)))) floor(sin_ref*2^(xy_width+ceil(log2(n_iter))))];
87	    
88	    dat = [floor(cos_z*2^(xy_width+ceil(log2(n_iter))-2)) floor(sin_z*2^(xy_width+ceil(log2(n_iter))-2))];
