    .gp_mode_rot_vec	        (`P_MODE_ROT_VEC),
    .gp_impl_unrolled_iterative (`P_IMPL_U_I),
    .gp_nr_iter 	        (`P_ITER),
    .gp_angle_width	        (`P_ATAN_LUT_WIDTH),
