    .gp_z_width 	        (`P_Z_WIDTH)
  ) dut (
    .i_rst_an(i_rst_an),
    .i_ena(i_ena),
    .i_clk(i_clk),
    .i_x(i_x),
    .i_y(i_y), 
    .i_z(i_z),
    .o_x(x_2_gain),
    .o_y(y_2_gain),
    .o_z(),
    .o_done()
  );

  cordic_gain #(
    .gp_mode_rot_vec (`P_MODE_ROT_VEC),
    .gp_gain_width   (`P_ATAN_GAIN_WIDTH),
    .gp_xy_width     (`P_XY_WIDTH),
    .gp_xy_owidth    ()
  ) gain_compensation (
    .i_cordic_x (x_2_gain),
    .i_cordic_y (y_2_gain),
    .o_cordic_x (),
    .o_cordic_y ()
  );

`ifdef VCD
